USE AdventureWorks2012;
GO

CREATE OR ALTER PROCEDURE usp_TransferProductInventory
    @ProductID       INT,
    @FromLocationID  INT,
    @ToLocationID    INT,
    @TransferQty     SMALLINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @AvailableQty SMALLINT;

    -- Step 2: fail fast, before opening a transaction, with a clear read
    SELECT @AvailableQty = Quantity
    FROM Production.ProductInventory
    WHERE ProductID = @ProductID AND LocationID = @FromLocationID;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Step 4: re-validate inside the transaction, THROW a custom business-rule error
        IF @AvailableQty IS NULL OR @AvailableQty < @TransferQty
            THROW 50001, 'Insufficient inventory at the source location for this transfer.', 1;

        UPDATE Production.ProductInventory
        SET Quantity = Quantity - @TransferQty
        WHERE ProductID = @ProductID AND LocationID = @FromLocationID;

        UPDATE Production.ProductInventory
        SET Quantity = Quantity + @TransferQty
        WHERE ProductID = @ProductID AND LocationID = @ToLocationID;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        THROW; -- re-raise the exact error (business-rule or system) to the caller
    END CATCH
END
GO

-- A transfer that should succeed
EXEC usp_TransferProductInventory
    @ProductID = 1, @FromLocationID = 1, @ToLocationID = 2, @TransferQty = 10;

-- A transfer that should fail cleanly, with no partial update
EXEC usp_TransferProductInventory
    @ProductID = 1, @FromLocationID = 1, @ToLocationID = 2, @TransferQty = 999999;
```
